#!/usr/bin/env python3
"""CW1 stage 3: write SEALED_PREDICTION.md from cw1.json (every number from the JSON) and its SHA-256.
python3 -I -B cw1_seal.py. kappa = 1/2 FITTED and held fixed; not theory closed."""
import hashlib, json, os
HERE = os.path.dirname(os.path.abspath(__file__)); R = json.load(open(os.path.join(HERE, "cw1.json")))
S = [1, 2, 3, 5, 7, 10, 15, 20, 30]; FORMS = ("PQ", "LOC3", "LOC1", "E55", "HALF"); GP = "1.9e-10"
STATUS = {"PQ": "reference; fails Cassini (KT16) and the planets (AZ12) on record",
          "LOC3": "the local rule on the 3D field; FAILS CASSINI at g* = c sqrt(G rho) on both footings (this lane, stage 2)",
          "LOC1": "the local rule in CZ2's 1D quadrature; passes Cassini only in that approximation; survives the MW on alt at prior-corner cells only",
          "E55": "fixed width 0.55 r_M; same class as HALF, not graded on the planets",
          "HALF": "fixed width 0.5 r_M; fails CZ3's planet gate"}
L = []; A = L.append
A("# CW1 sealed wide-binary prediction for Gaia DR4")
A("")
A("Sealed 2026-11-04, before any DR4 data, by lane `cw_lanes_2026_11_04/CW1_wide_binary_seal_dr4` (criteria da6917883b). Generated by `cw1_seal.py` from `cw1.json`; the SHA-256 of this file is in `SEALED_PREDICTION.sha256`. Separate from `prep_2026/gaia_dr4_prep/PREREGISTRATION_DR4.md`, which this lane never edited. κ = ½ FITTED; not theory closed. These are predictions of each form as defined, so DR4 can grade them. They are not a claim that any form is viable.")
A("")
A("**Conventions.** QUMOND with the simple ν, the host's **Newtonian** field in ν (observed 1.9e-10 m/s² inverted per footing; 1.778e-10 and 2.32e-10 bracket it in `cw1.json`). γ_r = radial internal field over GM/r², from an axisymmetric multipole solve with the anisotropic external field. Velocity boost γ_v = √γ_r. Footings: canonical a0 9.3603e-11, alt 1.1312e-10.")
A("")
A("## Status of each form (on record, and this lane)")
for f in FORMS: A(f"- **{f}**: {STATUS[f]}.")
A("")
A("## 1. γ_r, average over directions, at the primary field")
for foot in ("canonical", "alt"):
    A(f"\n**{foot}** (s in kAU)\n")
    A("| form | M (M☉) | " + " | ".join(str(v) for v in S) + " |"); A("|---|---|" + "---|" * len(S))
    for f in FORMS:
        for m in (0.5, 1.0, 1.5, 2.5):
            c = R["curves"][f"{foot}|{GP}|M{m}|{f}"]; A(f"| {f} | {m} | " + " | ".join(f"{v:.3f}" for v in c["avg"]) + " |")
A("\nAlong the Galactic-centre direction (mean of both senses) and perpendicular to it, M = 1.0 M☉. The along-field values carry ±0.003 from angular resolution (check K7); the averages, Q and γ_inf move ≤ 5e-7.\n")
for foot in ("canonical", "alt"):
    A(f"**{foot}**\n"); A("| form | dir | " + " | ".join(str(v) for v in S) + " |"); A("|---|---|" + "---|" * len(S))
    for f in FORMS:
        c = R["curves"][f"{foot}|{GP}|M1.0|{f}"]; A(f"| {f} | along | " + " | ".join(f"{v:.3f}" for v in c["par"]) + " |"); A(f"| {f} | perp | " + " | ".join(f"{v:.3f}" for v in c["perp"]) + " |")
    A("")
A("## 2. The inner-shape statistic Q (KT21's estimator)")
A("Q = ln median ṽ(2 ≤ y < 10) − ln median ṽ(y ≥ 10), y = G M/(a0 s_proj²), on the DR3 extract's pairs and geometry (40 orbits per pair, each pair's Galactic-centre direction). DR4 runs the same estimator on its own pairs. z is against DR3's Q_obs, σ = √(σ_stat² + 0.020²).\n")
A("| footing | Q_obs (DR3) | " + " | ".join(("N",) + FORMS) + " |"); A("|---|---|" + "---|" * 6)
for foot in ("canonical", "alt"):
    d = R["DR3"][foot]; p = d["pred"][GP]; A(f"| {foot} | {d['Q_obs']:+.4f} ± {d['sigma']:.4f} | " + " | ".join(f"{p[k]['Q_pred']:+.4f} (z {p[k]['z']:+.2f})" for k in ("N",) + FORMS) + " |")
A("\n## 3. What the frozen DR4 pipeline would return")
po = R["pipeline"]; A(f"The pipeline (`wide_binary_pipeline.py`, SHA-256 `{po['sha256']}`) imported read only: its DR4-noise population ({po['n_master']:,} master, {po['n_data']:,} per synthetic catalogue, {po['n_real']} catalogues per form), its declared-shape model grid and its fit. Each form's direction-averaged boost is injected at the true 3D separation.\n")
A("| footing | " + " | ".join(("N",) + FORMS) + " |"); A("|---|" + "---|" * 6)
for foot in ("canonical", "alt"):
    A(f"| {foot} | " + " | ".join(f"{po['out'][foot][k]['gamma_inf']:.3f} ± {po['out'][foot][k]['spread']:.3f}" for k in ("N",) + FORMS) + " |")
A("\nBin median over Newton's, pipeline bins of log10 y_proj (edges −1.5, −1.1, −0.8, −0.5, −0.2, 0.1, 0.5, 1.0, 2.2):\n")
A("| footing | form | " + " | ".join(f"b{i + 1}" for i in range(8)) + " |"); A("|---|---|" + "---|" * 8)
for foot in ("canonical", "alt"):
    for f in FORMS: A(f"| {foot} | {f} | " + " | ".join(f"{v:.3f}" for v in po["out"][foot][f]["ratio_to_N"]) + " |")
A("\n## 4. Separation labels (frozen lines: ΔQ / 0.020 and Δγ_inf / 0.028; ≥ 3 SEPARABLE, 2–3 MARGINAL)\n")
A("| footing | form | vs plain QUMOND | vs Newton |"); A("|---|---|---|---|")
for foot in ("canonical", "alt"):
    for f in FORMS[1:]:
        e = R["separation"][f"{foot}|{f}"]; A(f"| {foot} | {f} | {e['vs_plain']['label']} (ΔQ {e['vs_plain']['dQ']:.2f}, Δγ {e['vs_plain']['dgamma']:.2f}) | {e['vs_newton']['label']} (ΔQ {e['vs_newton']['dQ']:.2f}, Δγ {e['vs_newton']['dgamma']:.2f}) |")
    e = R["separation"][f"{foot}|PQ"]; A(f"| {foot} | PQ | – | {e['vs_newton']['label']} (ΔQ {e['vs_newton']['dQ']:.2f}, Δγ {e['vs_newton']['dgamma']:.2f}) |")
A("\n## 5. What DR4 would decide")
A("- A boost near the plain-QUMOND level beyond 10 kAU (pipeline γ_inf about 1.15–1.21) rules out every local-rule filter here (LOC3, LOC1).")
A("- A Newtonian result (γ_inf about 1.00) rules out plain QUMOND and the fixed-width filters (E55, HALF), and can't tell the local rule from Newton with the frozen statistic.")
A("- The local rule's own mark is a bump at about 4–10 kAU that is gone by about 15 kAU. The frozen scalar fit averages it away; only a binned or Q-type shape test can see it.")
A("\n## Checks behind the seal")
for k, v in R["checks"].items(): A(f"- {k} {'PASS' if v['ok'] else 'FAIL'}: {v['msg']}")
A("- K2 failed as frozen. The part even in μ matches the linear-response form to 3e-4 at x = 30 and 1e-5 at x ≥ 100. The odd part is second-order lopsidedness falling as 1/x (−8e-3 at 30, −9e-4 at 300). The sealed numbers aren't touched.")
A("- K7 failed as frozen. The difference sits only in the series evaluated exactly at μ = ±1 for PQ and LOC3. The along-field column carries ±0.003; nothing else moves more than 5e-7.")
open(os.path.join(HERE, "SEALED_PREDICTION.md"), "w").write("\n".join(L) + "\n")
h = hashlib.sha256(open(os.path.join(HERE, "SEALED_PREDICTION.md"), "rb").read()).hexdigest()
open(os.path.join(HERE, "SEALED_PREDICTION.sha256"), "w").write(f"{h}  SEALED_PREDICTION.md\n"); print(h)
